.glow-bleed{background: linear-gradient(135deg, oklch(0.9 0.1 50) 0%, oklch(0.75 0.2 45) 40%, oklch(0.65 0.25 30) 100%) text; -webkit-text-fill-color: transparent; animation: 4s ease-in-out 0s infinite alternate none running organicPulse;}
.liquid-terminals i{font-style: italic; letter-spacing: -0.04em; padding-right: 0.06em; font-weight: 400;}
.apple-sharpness{backdrop-filter: blur(15px); background: oklch(0.75 0.2 45 / 0.02); border: 0.5px solid oklch(0.75 0.2 45 / 0.15); box-shadow: oklch(0.9 0.1 50 / 0.05) 0px 1px 1px inset, rgba(0, 0, 0, 0.6) 0px 20px 40px; border-radius: 20px; transition: 0.5s cubic-bezier(0.16, 1, 0.3, 1);}
.apple-sharpness:hover{background: oklch(0.75 0.2 45 / 0.04); border-color: oklch(0.75 0.2 45 / 0.3);}
.sss-card{position: relative; overflow: hidden;}
.sss-card::before{content: ""; position: absolute; inset: -1px; border-radius: inherit; padding: 1px; background: linear-gradient(145deg, oklch(0.75 0.2 45 / 0.4), transparent 40%); mask: linear-gradient(rgb(255, 255, 255) 0px, rgb(255, 255, 255) 0px) content-box exclude, linear-gradient(rgb(255, 255, 255) 0px, rgb(255, 255, 255) 0px); pointer-events: none;}
.sss-card::after{content: ""; position: absolute; inset: 0px; border-radius: inherit; box-shadow: oklch(0.75 0.2 45 / 0.05) 0px 0px 40px inset; pointer-events: none; transition: box-shadow 0.4s;}
.sss-card:hover::after{box-shadow: oklch(0.75 0.2 45 / 0.15) 0px 0px 60px inset;}
.subsurface-glow{position: absolute; width: 150px; height: 150px; background: radial-gradient(circle, oklch(0.75 0.2 45 / 0.4) 0%, transparent 70%); border-radius: 50%; filter: blur(20px); opacity: 0; transition: opacity 0.5s; pointer-events: none; transform: translate(-50%, -50%); z-index: 0;}
.sss-card:hover .subsurface-glow{opacity: 1;}
.bloom-reveal{opacity: 0; transform: translateY(20px); filter: blur(8px); transition: opacity 1.4s cubic-bezier(0.16, 1, 0.3, 1), transform 1.4s cubic-bezier(0.16, 1, 0.3, 1), filter 1.4s;}
.bloom-reveal.active{opacity: 1; transform: translateY(0px); filter: blur(0px);}
.delay-100{transition-delay: 0.1s;}
.delay-200{transition-delay: 0.2s;}
.delay-300{transition-delay: 0.3s;}
